        return False
    if not matrix[0]:
        return False
    rows, cols = len(matrix), len(matrix[0])
    low, high = 0, rows * cols - 1
    while low <= high:
        mid = (low + high) // 2
        num = matrix[mid // cols][mid % cols]
        if num == target:
            return True
        elif num < target:
            low = mid + 1
        else:
