def frontier_play_pass(s, n):
    shiftText = ''
    for char in s:
        if char.isdigit():
            shiftText += str(9 - int(char))
        elif char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            offset = ord(char) - base
            shifted_offset = (offset + n) % 26
            shifted = chr(base + shifted_offset)
            shiftText += shifted
