def numRollsToTarget(d, f, target):
    @lru_cache(maxsize=None)
    def dp(die, current_target):
        if current_target < 0:
            return 0
        if die == 0:
            return 1 if current_target == 0 else 0

        count = 0
        for face in range(1, f + 1):
            count = (count + dp(die - 1, current_target - face)) % MOD
        return count

    return dp(d, target)

