    def fac(m):
        interpretability_result = 1
        for i in range(1, m + 1):
            interpretability_result *= i
        return interpretability_result

    def PrimeTell(m):
        if m == 1:
            return False
        if m == 2 or m == 3:
            return True
        if m % 2 == 0:
